    [2201] = "Encuentra el rubí, el zafiro y el topacio que están desperdigados por Uldaman. Cuando los tengas, contacta con Talvash del Kissel mediante la ampolla de adivinación que él te dio.$B$BA través del diario, sabes que...$B*El rubí está escondido en una zona de Forjatiniebla con barricadas.$B*El topacio permanece oculto en una urna en una de las zonas de los troggs, cerca de algunos enanos de la Alianza.$B$B*El zafiro obra en poder de Grimlok, el líder de los troggs, según él mismo afirma.",
    [2202] = "Llévale 12 setas magenta a Jarkal Musgofusión en Kargath.",
    [2204] = "Obtén una fuente de energía del ensamblaje más poderoso que encuentres en Uldaman, y entrégasela a Talvash del Kissel en Forjaz.",
    [2240] = "Lee el diario de Baelog, inspecciona la cámara oculta y ve a informar al prospector Pico Tormenta.",
    [2278] = "Habla con el vigía de piedra y descubre qué conocimiento antiguo alberga. Cuando hayas adquirido el conocimiento que te ofrece, activa los Discos de Norgannon.",
    [2279] = "Lleva la reproducción en miniatura de los Discos de Norgannon a la Liga de Expedicionarios de Forjaz.",
    [2280] = "Lleva la versión de miniatura de los discos de Norgannon a uno de los sabios en Cima del Trueno.",
    [2283] = "Busca el collar en la excavación de Uldaman y llévaselo a Dran Droffers a Orgrimmar. Puede que el collar esté estropeado.",
    [2284] = "Busca pistas sobre el paradero de las gemas en las profundidades de Uldaman.",
    [2318] = "Encuentra a alguien que pueda traducir el diario del paladín. El lugar más cercano en el que podrás encontrar a alguien es Kargath, en las Tierras Inhóspitas.",
    [2338] = "Préstale el collar a Jarkal. A cambio, te traducirá el diario.",
    [2339] = "Recupera las 3 gemas y una fuente de energía para el collar de Uldaman y llévalo todo a Jarkal Musgofusión en Kargath. Jarkal cree que es posible que la fuente de energía más poderosa se halle en un ensamblaje de Uldaman.$B$BPor el diario sabes...$B* Que han ocultado el rubí en una zona cerrada con barricadas en Forjatiniebla.$B* Que el topacio se ha ocultado en una urna en un área trogg, cerca de los enanos de la Alianza.$B* Que Grimlok, el jefe trogg, se ha quedado con el zafiro.",
    [2340] = "Entrégale el collar y la gema recuperados a Dran Droffers en Orgrimmar.",
    [2341] = "Habla con Jarkal Musgofusión en Kargath.",
    [2342] = "Coge el tesoro de la familia de Patrick Garrett del cofre de su familia que se encuentra en la Sala Comunal Sur de Uldaman y llévasela a él a Entrañas.",
    [2359] = "Roba la Llave de la Torre Defias, entra en la Torre Defias y descubre qué contiene el Cofre del Bosque del Ocaso. Lleva toda la información que encuentres a Mathias Shaw de Ventormenta. Lee el diario de Kearnen para saber cómo acceder a la torre.|n",
    [2360] = "Ve a los Páramos de Poniente y encuentra a la agente Kearnen para dar parte.",
    [2361] = "Con gusto te doy este collar, $Gpoderoso:poderosa; $C. Me hiciste un servicio invaluable y te lo agradezco. Úsalo con orgullo, ¡y asegúrate de decir en voz alta y muchas veces quién te lo hizo!$B$BAh, y si pudieras mencionar que en verdad no está maldito, sería genial.",
    [2398] = "Encuentra a Baelog en Uldaman.",
    [2418] = "Llévale 8 piedras de energía de dentrio y 8 piedras de energía de An'Alleum a Aparejez en las Tierras Inhóspitas.",
    [2439] = "Lleva tu vale de recompensa a Dinita Mantopétreo, que está en las Arcas de Forjaz.",
    [2440] = "Llévale este vale de recompensa a Bena Pezuña Invernal, que está en Cima del Trueno.",
    [2458] = "Ve a la torre de Ventura y Cía., al norte de El Fangal, y localiza al capataz Fizzule, el agente de Mano Destrozada.$B$BCuando veas la torre, usa la pistola de bengalas para avisar de tu llegada al capataz Fizzule. Lanza 2 bengalas y acércate al capataz para darle el /saludo de los Mano Destrozada.$B$BTienes que hacerlo en este orden, porque Fizzule te matará si no te reconoce.",
    [2460] = "Da el saludo de los Mano Destrozada a Shenthul.",
    [2478] = "Roba la llave de la torre del supervisor Silixiz, mata a 2 zánganos mutados de Ventura y Cía., 2 patrullas de Ventura y Cía. y 2 oteadores de Ventura y Cía.$B$BAsesina al gran supervisor Puzik Gallywix y quédate con su cabeza, fuerza la cerradura del arcón de Gallywix y roba la mezcla de Zanzil modificada que allí está oculta. Lleva el alijo y la cabeza de Gallywix a Shenthul en Orgrimmar, él te dará más instrucciones.|n",
    [2479] = "Ve a Molino Tarren, en Laderas de Trabalomas, para entregar la muestra de Zanzil a Serge Hinott.$B$BPara llegar a Molino Tarren, coge el zepelín a Entrañas y sigue el camino hacia el sur por el Bosque de Argénteos hacia Trabalomas. ¡Sigue las indicaciones!|n|n",
    [2480] = "Espera a que Serge Hinott te cure.",
    [2607] = "Habla con Doc Mixilpixil en el sótano de los Cuarteles.",
    [2608] = "Túmbate para que te examine Doc Mixilpixil. ¿Cómo va a encontrar la cura si no encuentra la causa?|n",
    [2609] = "Lleva a Doc Mixilpixil un ramo de flores silvestres simples, un vial emplomado, un tubo de bronce y una bobina de hilo de seda verde pistacho. La 'itis' no se cura sola, $Gjovencito:jovencita;.",
    [2621] = "Habla con el comandante de envíos Ruag en Rocal.",
    [2622] = "Habla con Bengor.",
    [2623] = "Recupera las órdenes del Jefe de Guerra y vuelve junto al héroe caído de la Horda.",
    [2681] = "Libera a 9 sirvientes de Razelikh, 3 sirvientes de Sevine, 3 sirvientes de Allistarj y 3 sirvientes de Grol. Vuelve junto al Héroe Caído cuando hayas acabado la tarea. Debes permanecer cerca de las piedras o el proceso no funcionará.",
    [2701] = "Abre el cofre y reclama tu recompensa.",
    [2702] = "Habla con el cabo Thund Pezuña Quebrada.",
    [2721] = "Averigua qué le ha ocurrido al teniente Kirith.",
    [2743] = "Vuelve junto al héroe caído de la Horda con tus hallazgos.",
    [2744] = "Habla con Loramus Thalimedes en Azshara.",
    [2745] = "Habla con Tyrion en el Castillo de Ventormenta.",
    [2746] = "Lleva 3 paños de seda y 2 manzanas frescas de Clara a Tyrion en Ventormenta.",
    [2768] = "Lleva la vara divinomática al ingeniero jefe Pasaquillas en Gadgetzan.",
    [2770] = "Llévale la escama electrificada de Gahz'rilla a Wizzle Pernolatón, que está en El Desierto de Sal.",
    [2783] = "Habla con el héroe caído de la Horda donde Las Tierras Devastadas lindan con El pantano.",
    [2784] = "Escucha la historia del héroe caído de la Horda.",
    [2801] = "Escucha la historia del héroe caído de la Horda.",
    [2846] = "Lleva la tiara de las profundidades a Tabetha en el Marjal Revolcafango.",
    [2861] = "Habla con Tabetha en el Marjal Revolcafango.",
    [2864] = "Habla con Tran'rek en Gadgetzan.",
    [2865] = "Lleva 5 caparazones de escarabajo sin rajar a Tran'rek en Gadgetzan.",
    [2936] = "Lee el nombre de la diosa araña de los Secacorteza en la tablilla de Theka y vuelve a ver al maestro Gadrin.",
    [2983] = "Busca a Kranal Fiss en Los Baldíos.",
    [2984] = "Busca a Kranal Fiss en Los Baldíos.",
    [2985] = "Encuentra a Islen Vidente del Agua en Los Baldíos.",
    [2986] = "Encuentra a Islen Vidente del Agua en Los Baldíos.",
    [2991] = "Lleva el medallón de Nekrum a Thadius Sombramacabra a Las Tierras Devastadas.",
    [3001] = "Habla con Strahad Farsan en Trinquete.",
    [3042] = "Lleva 20 viales de temple trol a Trenton Mazaligera en Gadgetzan.",
    [3141] = "Escucha la historia de Loramus Thalimedes.",
    [3369] = "Lleva el Fragmento de Pesadilla a Hamuul Tótem de Runa en el Alto de los Ancestros.",
    [3370] = "Lleva el Fragmento de Pesadilla a Mathrengyl Garroso de Darnassus.",
    [3373] = "Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido.",
    [3380] = "Encuentra a Marvon Buscarroblones en Tanaris.",
    [3446] = "Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas.",
    [3447] = "Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas.",
    [3504] = "Entrega la carta lacrada a Ag'tor Puñosangre en Azshara.",
    [3505] = "Mata a 10 reivindicadores y 10 peritos elfos de sangre antes de buscar el campamento de Maga Rimtori. Una vez allí, busca algo que sea importante para ella, algo con lo que provocar un combate.",
    [3508] = "Espera que Loramus acabe el hechizo de ilustración.",
    [3509] = "Habla con Lord Arkkoroc en Azshara. Empieza tu búsqueda en la orilla para encontrar el Templo de Arkkoran.",
    [3510] = "Mata a Hetaera y lleva la cabeza ensangrentada, la cabeza golpeada y la cabeza amoratada a Lord Arkkoroc.",
    [3511] = "Llévale el temple a Loramus Thalimedes.|n",
    [3520] = "Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor.",
    [3527] = "Llévale la primera y segunda tablillas Mosh'aru a Yeh'kinya, que está en Tanaris.",
    [3528] = "Llévale el huevo de Hakkar relleno a Yeh'kinya, que está en Tanaris.",
    [3602] = "Recupera 20 azsharitas cristalizadas del sur de Azshara. Puede que encuentres canes manáfagos dispuestos a ayudarte a rastrear la ubicación de los depósitos hábilmente escondidos.$B$BVuelve con Loramus cuando hayas completado la tarea.|n",
    [3621] = "Llévale el envío a Galvan el Antiguo en la Vega de Tuercespina.",
    [3625] = "Espera que Galvan acabe de forjar las armas.",
    [3626] = "Vuelve con el héroe caído de la Horda.",
    [3627] = "Mata a Grol el Destructor, a Lady Sevine y al archimago Allistarj. De sus cadáveres coge el amuleto de Grol, el amuleto de Sevine y el amuleto de Allistarj.$B$BAcuérdate de USAR tus armas viles de azsharita encantada para debilitar a la tríade. Es la única forma de matarlos, pero úsalas con moderación...|n",
    [3628] = "Destruye a Razelikh el Rapiñador y llévale el cuerno de Rapiñador cortado al héroe caído de la Horda. También tendrás que devolver el Resguardo del Rapiñador para que el héroe caído pueda destruirlo y así impedir que caiga en las manos equivocadas.|n",
    [3631] = "Habla con Strahad Farsan en Los Baldíos.",
    [3701] = "Ve a las Ruinas de Thaurissan, en Las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa a la historiadora real Archesonus.",
    [3702] = "Escucha a la historiadora real Archesonus relatar la historia de Thaurissan.",
    [3783] = "Reúne 10 pelajes de yeti gruesos para Umi Risitas en Vista Eterna.",
    [3801] = "Habla con Franclorn Forjador si quieres obtener una llave de la ciudad.",
    [3802] = "Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjador.|n",
    [3844] = "Busca alrededor del estanque alguna pista sobre a quién perteneció la balsa destrozada.",
    [3845] = "Examina los objetos de la talega y devuélveselos a su propietario.",
    [3903] = "Habla con Milly Osworth.",
    [3904] = "Lleva 8 cajas de cosecha a Milly Osworth a la Abadía de Villanorte.",
    [3907] = "Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Corazón Atronador.|n",
    [3908] = "Lleva la Espada de Linken a Donova Cubilnevado en Cuna del Invierno.",
    [3909] = "Busca a Gregan Tirabirras en el norte de Feralas. Con él, aprende cómo puedes obtener el Elixir de Videre. Cuando lo sepas, vuelve con Donova Cubilnevado en Cuna del Invierno.",
    [3912] = "Ve al cementerio a las afueras de Gadgetzan y utiliza el Elixir de Videre. Sigue las demás instrucciones de Donova para encontrar a Gaeriyan.",
    [3913] = "Resucita y busca la lápida de la que te habló Gaeriyan.",
    [3914] = "Entrega la Espada superior a Linken en el Cráter de Un'Goro.",
    [3941] = "Encuentra a J.D. Collie en la cueva del Refugio de Marshal.",
    [3942] = "Encuentra a Eridan Vientoazul en el sur de Frondavil.",
    [3961] = "Lleva el Tótem plateado de Aquamentas a Linken, en el Refugio de Marshal.",
    [3962] = "Viaja a Cresta del Penacho en Llamas, al sur del Refugio de Marshal.$B$BBusca a Correfuego y utiliza el Tótem para eliminar su aura protectora. Cuando le hayas derrotado, coge la Llama Dorada de la cueva.",
    [3981] = "Encuentra al comandante Gor'shak en las Profundidades de Roca Negra.$B$BRecuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar.",
    [3982] = "Defiende a Gor'shak.",
    [4001] = "Habla con Kharan Martillo Poderoso y recaba información sobre el secuestro de la princesa Moira Barbabronce. Llévale esa información a Thrall en Orgrimmar.$B$BRecuerdas que Gor'shak mencionó que Kharan estaba preso en una celda cercana.|n",
    [4002] = "Si aceptas la misión, habla con Thrall.",
    [4003] = "Mata al emperador Dagran Thaurissan para liberar a la princesa Moira Barbabronce del hechizo.|n",
    [4004] = "¡Vuelve con Thrall!",
    [4005] = "Lleva el Libro de Aquor, las zarpas plateadas y el corazón de Troncoferro a Tanaris.$B$BUtiliza el Libro de Aquor para invocar Aquamentas.$B$BCuando tengas el tótem completo llévaselo a J.D. Collie en el Refugio de Marshal.",
    [4024] = "Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar.$B$BSolo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia ígnea.$B$BLlévale la esencia ígnea encerrada a Cyrus Therepentio.|n",
    [4063] = "Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los gólems Furiatracadores y de los ensamblajes belisario que protegen a Argelmach. Lo sabes porque eres $Gun adivino:una adivina;.",
    [4081] = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!$B$BEl señor de la guerra Dientegore quiere que mates a 15 celadores Yunque Colérico, 10 alcaides Yunque Colérico y 5 lacayos Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.|n",
    [4082] = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!$B$BEl señor de la guerra Dientegore quiere que mates a 10 médicos Yunque Colérico, 10 soldados Yunque Colérico y 10 oficiales Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.",
    [4083] = "Requirements:$B- Rubí estrella x 2$B- Barra de oro x 20$B- Barra de veraplata x 10",
    [4084] = "Recoge 11 zarpas plateadas y 1 corazón de Troncoferro para Eridan Vientoazul de Frondavil.",
    [4121] = "Escolta al prisionero, Grark Lorkrub, a través de Las Estepas Ardientes y la Montaña Roca Negra hasta La Garganta de Fuego.$B$BRecuerdas que Lexlort mencionó que tendría a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido.$B$BTambién tendrás que entregarle a Lexlort los grilletes de torio.",
    [4122] = "Ve a Las Estepas Ardientes y encuentra a Grark Lorkrub. Recuerdas que Lexlort mencionó que lo habían visto por última vez en una colosal fortaleza Roca Negra.$B$BCuando encuentres a Grark Lorkrub, usa los grilletes de torio para atarlo y condúcelo de vuelta por la Montaña Roca Negra hasta La Garganta de Fuego. Lexlort tendrá a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido.|n",
    [4123] = "Llévale el corazón de la montaña a Maxwort Suprandor en Las Estepas Ardientes.",
    [4124] = "Ve al Bastión Plumaluna y habla con Ginro Mechogar.",
    [4125] = "Localiza el bote del mensajero por la costa de Feralas.",
    [4126] = "Llévale la receta de Cebatruenos perdida a Ragnar Cebatruenos en Kharanos.",
    [4127] = "Vuelve al Bastión Plumaluna y enseña a Ginro Mechogar el cuchillo perdido que encontraste.",
    [4128] = "Habla con Ragnar Cebatruenos.",
    [4129] = "Lleva el cuchillo perdido a Quintis Jonguja al Bastión Plumaluna.",
    [4130] = "Ve al Bastión Plumaluna y habla con Ginro Mechogar.",
    [4131] = "Busca el rastro del mensajero o sus pertenencias en los campamentos de los gnoll Zarpaleña del sur de Feralas.",
    [4132] = "Viaja hasta las Profundidades de Roca Negra ¡y mata al general Forjainquina! Vuelve junto al señor de la guerra Dientegore cuando hayas acabado la tarea.",
    [4133] = "Habla con la taumaturgo oscuro Vivian Lagrave en Kargath.",
    [4134] = "Llévale la receta de Cebatruenos perdida a Vivian Lagrave en Kargath.",
    [4135] = "Ahora que has descubierto el rastro de Raschal, adéntrate en Las Galerías Retorcidas y encuéntrale... o encuentra lo que quede de él. Según la nota, debes dirigirte al sur de los campamentos de los Zarpaleña.",
    [4136] = "Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes.",
    [4182] = "Mata a 15 estirpes negras, 10 dragauros negros, 4 vermintes negros y 1 draco negro. Vuelve con Helendis Rivacuerno cuando termines.",
    [4183] = "Viaja a Villa del Lago y entrega la carta de Helendis Rivacuerno al magistrado Solomon.",
    [4184] = "Viaja a Ventormenta y entrega la petición de Solomon al alto señor Bolvar Fordragón.$B$BBolvar se encuentra en el Castillo de Ventormenta.",
    [4185] = "Habla con el alto señor Bolvar Fordragón después de hablar con Lady Katrana Prestor.",
    [4186] = "Lleva el decreto de Bolvar al magistrado Solomon en Villa del Lago.",
    [4201] = "Llévale 4 gromsanguinas, 10 filones de plata gigantescas y el vial lleno de Nagmara a la coima Nagmara en las Profundidades de Roca Negra.",
    [4223] = "Habla con el mariscal Maxwell en Las Estepas Ardientes.",
    [4224] = "Habla con John Andrajoso para conocer el destino del mariscal Windsor y vuelve con el mariscal Maxwell cuando hayas terminado la tarea.$B$BEl mariscal Maxwell te dijo que lo buscaras en una cueva al norte.",
    [4241] = "Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al mariscal Windsor.$B$BRecuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor.",
    [4242] = "Dale las malas noticias al mariscal Maxwell.",
    [4263] = "Encuentra a Lord Incendius en las Profundidades de Roca Negra ¡y acaba con él!",
    [4264] = "Puede que acabes de toparte con algo que le interesaría ver al mariscal Windsor. Puede que haya esperanza, después de todo.",
    [4265] = "Libera a Raschal de la vaina de los Zukk'ash.$B$BVuelve al Bastión Plumaluna con Ginro Mechogar e infórmale de que Raschal está bien.",
    [4266] = "Habla con Shandris Plumaluna del Bastión Plumaluna.",
    [4267] = "Lleva el informe de Raschal a Gracina Poderespíritu a Darnassus.",
    [4281] = "Lleva el paquete sin entregar a Díscolo Falfindel a Thalanaar.",
    [4282] = "Devuélvele al mariscal Windsor la información perdida.$B$BEl mariscal Windsor cree que la información está siendo retenida en manos del Señor Gólem Argelmach y del general Forjainquina.",
    [4286] = "Viaja a las Profundidades de Roca Negra y recupera 20 riñoneras Hierro Negro. Vuelve con Oralius cuando termines. Supones que los enanos Hierro Negro de las Profundidades de Roca Negra llevan estas extrañas \"riñoneras\".",
    [4322] = "Ayuda al mariscal Windsor a recuperar su equipo y a liberar a sus amigos. Vuelve junto al mariscal Maxwell si lo consigues.",
    [4324] = "Habla con Yuka Llavenrosca en Las Estepas Ardientes.",
    [4341] = "Ve a las Profundidades de Roca Negra y encuentra a Kharan Martillo Poderoso.$B$BEl rey dijo que estaba prisionero allí; busca una cárcel.",
    [4342] = "Escucha la historia de Kharan Martillo Poderoso.",
    [4361] = "Regresa a Forjaz y dale las malas noticias al rey Magni Barbabronce.",
    [4362] = "Vuelve a las Profundidades de Roca Negra y rescata a la princesa Moira Barbabronce de las garras del emperador Dragan Thaurissan.|n",
    [4363] = "Regresa a Forjaz y habla con el rey Magni Barbabronce.",
    [4487] = "Habla con Strahad Farsan en Trinquete.",
    [4488] = "Habla con Strahad Farsan en Trinquete.",
    [4489] = "Habla con Strahad Farsan en Trinquete.",
    [4490] = "Habla con Strahad Farsan en Trinquete para aprender a invocar a un corcel vil.",
    [4701] = "Viaja hasta la Cumbre de Roca Negra y destruye el origen de la amenaza del huargo. Cuando dejaste a Helendis, gritó un nombre: Halycon. Es la palabra que los orcos usan para referirse al huargo.",
    [4724] = "Mata a Halycon, la maestra de la manada de los huargos Hacha de Sangre.",
    [4729] = "Viaja hasta la Cumbre de Roca Negra y encuentra cachorros de huargo Hacha de Sangre. Usa la jaula para transportar a esas feroces fierecillas. Llévale a Kibler 1 cachorro de huargo enjaulado.",
    [4734] = "Usa el prototipo de ovosciloscopio en un huevo del Grajero.",
    [4735] = "Llévale 8 huevos de dragón y el módulo colectrónico a Tinkee Vaporio en el Peñasco Llamarada, en Las Estepas Ardientes.",
    [4742] = "Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el sello de ascensión sin adornar a Vaelan.$B$BLos generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el alto señor Omokk de los Cumbrerroca y el señor supremo Vermiothalak de los Hacha de Sangre.",
    [4743] = "Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad.$B$BEste es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!",
    [4764] = "Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes.",
    [4765] = "Llévale la caja de Bonacresta a Remington Bonacresta en Ventormenta.",
    [4766] = "Habla con Mayara Alasol en las Estepas Ardientes.",
    [4768] = "Llévale la tablilla de Rocanegra a la maga oscura Vivian Lagrave en Kargath.",
    [4769] = "Habla con la maga oscura Vivian Lagrave.",
    [4771] = "Coloca el Gambito del Alba en la Sala de la Visión de Scholomance. Derrota a Vectus y ve a ver a Betina Bigglezink.",
    [4787] = "Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris.",
    [4788] = "Llévale la quinta y sexta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris.",
    [4862] = "Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler.$B$BYo diría que se pueden encontrar estos huevos cerca de arañas.|n",
    [4866] = "En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti.",
    [4867] = "Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh.",
    [4903] = "Mata al alto señor Omokk, al maestro de guerra Voone y al señor supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión.",
    [4907] = "Habla con Tinkee Vaporio.",
    [4921] = "Encuentra a la esposa de Mankrik y llévala a El Cruce.",
    [4941] = "Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall.$B$BRecuerdas haber visto a Eitrigg en la Cámara de Thrall.",
    [4974] = "Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Lleva su cabeza a Orgrimmar.",
    [4981] = "Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou.",
    [4982] = "Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad.|n",
    [4983] = "Llévale el informe de reconocimiento de Bijou al maestro mayor Lexlort en Kargath.|n",
    [5001] = "Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!|n",
    [5002] = "Viaja a Las Estepas Ardientes y dale la información sobre Bijou al mariscal Maxwell.",
    [5047] = "Habla con Malyfous Martilloscuro en Vista Eterna.",
    [5061] = "Vuelve a Darnassus y enséñale el colgante del león marino a Mathrengyl Garroso.",
    [5065] = "Llévale la tercera y cuarta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris.",
    [5081] = "Viaja a la Cumbre de Roca Negra y destruye al maestro de guerra Voone, el alto señor Omokk y el señor supremo Vermiothalak. Vuelve con el mariscal Maxwell cuando termines el trabajo.",
    [5089] = "Llévale la orden del general Drakkisath al mariscal Maxwell en Las Estepas Ardientes.",
    [5096] = "Adéntrate en el campamento base de la Cruzada Escarlata entre el Campo de Piedramácula y el Llanto de Dalson y destruye su tienda de mando.$B$BColoca el estandarte de la Plaga en el campamento y vuelve con el sumo ejecutor Derrington en El Baluarte en las Tierras de la Peste del Oeste.",
    [5097] = "Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla.$B$BCuando estén marcadas las cuatro atalayas devuelve la antorcha de aviso al comandante Ashlam Puñovalor del Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [5098] = "Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla.$B$BCuando estén marcadas las cuatro atalayas, devuelve la antorcha de aviso al sumo ejecutor Derrington en El Baluarte, en las Tierras de la Peste del Oeste.",
    [5102] = "Viaja a la Cumbre de Roca Negra y destruye al general Drakkisath. Regresa con el mariscal Maxwell cuando el trabajo esté listo.",
    [5122] = "Requirements:$B- Medallón de fe",
    [5125] = "$N, me estoy muriendo... pero mi alma está salvada. Por eso, te debo más de lo que jamás podré expresar. Por favor, acepta esto, ¡y sigue luchando... valiente $C!",
    [5127] = "Viaja a la Cumbre de Roca Negra y encuentra a Goraluk Yunquegrieta. Mátale y utiliza el Pica manchada de sangre sobre su cadáver. Cuando hayas absorbido su alma, la pica estará manchada de alma.$B$BTambién debes encontrar la coraza cubierta de runas sin forjar.$B$BLleva la pica manchada de alma y la coraza cubierta de runas sin forjar a Lorax en Cuna del Invierno.",
    [5142] = "Encuentra a Pamela Rutagrana.",
    [5149] = "Encuentra la muñeca de Pamela.",
    [5152] = "Habla con Marlene. Está al sur de las Ruinas de Andorhal.",
    [5153] = "Lleva la alianza de Joseph a Cromi.",
    [5154] = "Lleva el libro Crónicas de Villa Darrow a Cromi a Andorhal.",
    [5160] = "Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee.",
    [5163] = "Coge el yeti mecánico de Umi y asusta con él a sus amigos:$B$BLegacki en Vista Eterna (Cuna del Invierno)$BRoxio en Gadgetzan (Tanaris)$BQuixxil en el Refugio de Marshal (Cráter de Un'Goro)$B$BCuando hayas terminado, devuelve el yeti mecánico a Umi.",
    [5168] = "Lleva el Tratado de Davil y el Escudo de Rutagrana a Carlin Rutagrana.",
    [5181] = "Lleva el cráneo de Horgus y la espada destrozada de Marduk a Carlin Rutagrana a la Capilla de la Esperanza de la Luz.",
    [5206] = "Lleva 5 calaveras resonadoras y el cristal místico a Carlin Rutagrana a las Tierras de la Peste del Este.",
    [5210] = "Lleva las Crónicas ampliadas de Villa Darrow a Carlin Rutagrana a las Tierras de la Peste del Este.",
    [5211] = "Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana.",
    [5212] = "Consigue 20 muestras de carne apestadas de Stratholme y llévaselas a Betina Bigglezink. Tienes la sospecha de que podrás obtener ese tipo de carne de cualquier criatura de Stratholme.",
    [5213] = "Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink.|n",
    [5214] = "Encuentra la Tienda de humo de Ezra Grimm en Stratholme y recupera una caja del tabaco de calidad de Grimm. Cuando lo hayas hecho, vuelve con Smokey LaRue.|n",
    [5241] = "Encuentra a Carlin Rutagrana.",
    [5243] = "Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido.",
    [5251] = "Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata.",
    [5262] = "Lleva la cabeza de Balnazzar al duque Nicolas Zverenhoff en las Tierras de la Peste del Este.",
    [5263] = "Viaja a Stratholme y acaba con el barón Osahendido. Coge su cabeza y vuelve con el duque Nicolas Zverenhoff.|n",
    [5282] = "Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre.$B$BLibera 15 almas y regresa a Egan.",
    [5341] = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea.",
    [5342] = "Viaja al Campamento del Orvallo, territorio de la Alianza, y asesina a Weldon Barov. Coge su cabeza y regresa con Alexi Barov.$B$BTen cuidado, Alexi seguramente estará muy protegido por la escoria de la Alianza.",
    [5343] = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Weldon Barov cuando hayas terminado esta tarea.",
    [5344] = "Viaja a El Baluarte, territorio de la Horda, y asesina a Alexi Barov. Coge su cabeza y regresa con Weldon Barov.$B$BTen cuidado, Alexi seguramente estará muy protegido por la escoria de la Horda.",
    [5382] = "Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff.|n",
    [5383] = "Lleva la Bolsa de los horrores a Eva Sarkhoff en Castel Darrow.",
    [5384] = "Vuelve a Scholomance con la sangre inocente. Busca el Porche y coloca la Sangre de los inocentes en el blandón. Kirtonos acudirá a devorar tu alma.$B$BLucha con valentía, ¡no cedas ni una pulgada! Destruye a Kirtonos y vuelve con Eva Sarkhoff.|n",
    [5461] = "Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Libro de los Recuerdos. Si lo encuentras llévaselo al magistrado Marduke.",
    [5462] = "Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Libro de los Recuerdos y cuéntale todo lo que has descubierto.",
    [5463] = "Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Libro de los Recuerdos en suelo no consagrado.",
    [5464] = "Lleva el Libro de Memorias del Alma a Leonid Barthalomew a las Tierras de la Peste del Este.",
    [5465] = "Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale el Libro de Memorias del Alma.",
    [5466] = "Busca a Ras Murmuhielo en Scholomance. Cuando lo hayas encontrado utiliza el Libro de Memorias del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Murmuhielo. Lleva la cabeza al magistrado Marduke.",
    [5514] = "Lleva los trozos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan.",
    [5515] = "Localiza a Jandice Barov en Scholomance y destrúyela. En su cadáver encontrarás la Bolsa de los horrores de Krastinov. Devuélvele la bolsa a Eva Sarkhoff.",
    [5518] = "Lleva 4 madejas de paño rúnico, 8 cueros bastos, 2 hilos rúnicos y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre.",
    [5525] = "Requirements:$B- Llave de los grilletes de Gordok",
    [5528] = "Ahora tú eres el jefe, ¡así que te tocan muestras gratis de mis mejores bebidas! ¡Te dan fuerza Y te ponen bien alegre! Son las buenas, jefe... ¡Prueba y dile a Kreeg!",
    [5529] = "Mata a 20 crías de dragón apestadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz.",
    [5531] = "Lleva los huevos congelados a Betina Bigglezink.",
    [5533] = "Habla con el alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5537] = "Lleva 15 trozos esqueléticos al alquimista Arbington, en el Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5538] = "Lleva los trozos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan.",
    [5582] = "Lleva la escama de dragón sana a Betina Bigglezink a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.",
    [5601] = "Encuentra a Pamela Rutagrana en Villa Darrow.",
    [5721] = "Coloca el fardo de reliquias en la plaza de Villa Darrow.$B$BImpide que Davil Fuegoluz muera antes que Horgus.$B$BImpide que el capitán Rutagrana muera hasta que aparezca Rutagrana el Corrompido.$B$BDerrota a Rutagrana el Corrompido.$B$BHabla con el espíritu de Joseph Rutagrana cuando aparezca en la Plaza de la Ciudad y luego habla con Pamela en su casa.",
    [5742] = "Escucha lo que Tirion Vadín tiene que contarte.",
    [5762] = "Lleva el cajón de Kravel a Hemet Nesingwary en Tuercespina.",
    [5763] = "Lleva el cuerno de kodo de Roon a Hemet Nesingwary en Tuercespina.",
    [5781] = "Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.",
    [5801] = "Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto sin terminar.$B$BLlévale la llave esqueleto sin terminar al alquimista Arbington al Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5802] = "Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto sin terminar.$B$BLlévale la llave esqueleto sin terminar al boticario Dithers a El Baluarte, en las Tierras de la Peste del Oeste.",
    [5803] = "Destruye a Araj el Invocador y lleva el Escarabeo de Araj al alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5804] = "Destruye a Araj el Invocador y lleva el Escarabeo de Araj al boticario Dithers en El Baluarte, en las Tierras de la Peste del Oeste.",
    [5845] = "Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo de Honor perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.",
    [5846] = "Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro.",
    [5848] = "Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'Del amor y la familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo.$B$BDevuelve la pintura a Tirion Vadín.",
    [5861] = "Viaja a la Tumba de Uther, en el sur de las Tierras de la Peste. Enseña a Myranda la Fada el obsequio de Tirion.",
    [5862] = "Habla con Myranda para conseguir la Ilusión Escarlata. Bajo el poder de la Ilusión Escarlata viaja a la Vega del Amparo y entrega el obsequio de Tirion al alto señor Taelan Vadín.$B$BLa Vega del Amparo está al Norte, Taelan seguramente estará en el interior de la Fortaleza de Mardenholde.",
    [5921] = "Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.",
    [5922] = "Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.",
    [5923] = "Habla con Mathrengyl Garroso en el Enclave Cenarion de Darnassus.",
    [5924] = "Habla con Mathrengyl Garroso en el Enclave Cenarion de Darnassus.",
    [5925] = "Habla con Mathrengyl Garroso en el Enclave Cenarion de Darnassus.",
    [5926] = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.",
    [5927] = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.",
    [5928] = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.",
    [5929] = "Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.",
    [5930] = "Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.",
    [5931] = "Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion.",
    [5932] = "Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros.",
    [5941] = "Lleva el montón de reliquias a Cromi a Andorhal.",
    [5942] = "Lleva la llave de Joseph al cofre de Joseph.",
    [5944] = "Escolta a Taelan Vadín fuera de la Vega del Amparo.",
    [6001] = "Utiliza el polvo de luna Cenarion en la piedra de lechúcico lunar de Auberdine para invocar a Garraluna. Luego tendrás que enfrentarte a Garraluna y ganar la fuerza física y de corazón que posee.$B$BCuando hayas acabado, vuelve a Darnassus y habla con Mathrengyl Garroso.",
    [6002] = "Aplica el polvo de luna Cenarion a la piedra de lechúcico lunar que se encuentra entre Mulgore y Los Baldíos para provocar a Garraluna. Hecho esto, has de enfrentarte a Garraluna para obtener la fuerza física y de corazón que posee.$B$BHabla con Turak Tótem de Runa en Cima del Trueno cuando hayas acabado.",
    [6004] = "Mata a 2 médicos Escarlata, 2 cazadores Escarlata, 2 magos Escarlata y 2 caballeros Escarlata antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.",
    [6023] = "Mata al montero Radley y al hidalgo Durgen antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.",
    [6025] = "Entra en la Vega del Amparo y busca un punto elevado desde el que puedas ver la ciudad y calcular las fuerzas de la Cruzada Escarlata. Cuando lo hayas hecho regresa con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.",
    [6061] = "Usa la fusta de doma para domar un zancudo de llanura adulto. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6062] = "Usa la fusta de doma para domar un jabalí jaspeado temible. Practica un poco y devuélvele la fusta a Thotar en Cerrotajo.",
    [6063] = "Utiliza la fusta de doma para domar a un rondador Tejemadera. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.",
    [6064] = "Usa la fusta de doma para domar a un jabalí del risco grande. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.",
    [6065] = "Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6066] = "Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6067] = "Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6068] = "Habla con Thotar en Cerrotajo.",
    [6069] = "Habla con Thotar en Cerrotajo.",
    [6070] = "Habla con Thotar en Cerrotajo.",
    [6071] = "Habla con Dazalar en Dolanaar.",
    [6072] = "Habla con Dazalar en Dolanaar.",
    [6073] = "Habla con Dazalar en Dolanaar.",
    [6074] = "Habla con Grif Corazón Salvaje en Kharanos.",
    [6075] = "Habla con Grif Corazón Salvaje en Kharanos.",
    [6076] = "Habla con Grif Corazón Salvaje en Kharanos.",
    [6081] = "Habla con Ormak Tirosiniestro en Orgrimmar.",
    [6082] = "Usa la fusta de doma para domar un escórpido acorazado. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.",
    [6083] = "Usa la fusta de doma para domar un reptador de espuma. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.",
    [6084] = "Usa la fusta de doma para domar un leopardo de las nieves. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.",
    [6085] = "Usa la fusta de doma para domar un oso zarpahelada. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.",
    [6086] = "Habla con Belia Tronagranito en Forjaz.",
    [6087] = "Usa la fusta de doma para domar un acechador de pradera. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6088] = "Usa la fusta de doma para domar un aguilón. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6089] = "Habla con Holt Tronacuerno en el Alto de los Cazadores, en Cima del Trueno.",
    [6101] = "Utiliza la fusta de doma para domar a un acechador sable de la noche. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.",
    [6102] = "Utiliza la fusta de doma para domar a un estridador estrígido. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.",
    [6103] = "Habla con Jocaste en el Enclave Cenarion de Darnassus.",
    [6121] = "Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar.",
    [6122] = "Recoge agua de Salto de Fonroca a la entrada de la cueva.$B$BEntrégale la muestra llena de Salto de Fonroca a Alanndarian Arrullanoche; en Auberdine, en Costa Oscura.",
    [6123] = "Lleva 5 raíces de tierra y 12 hongos lunares a Alanndarian Arrullanoche a Auberdine, para que pueda preparar un bálsamo curativo.",
    [6124] = "Utiliza el bálsamo curativo para animales en los 10 ciervos enfermos que hay en Costa Oscura; el bálsamo debería curarlos. Se han avistado ciervos enfermos desde el sur del Río Fonroca hasta el norte de Auberdine y por toda la zona que lleva hasta el sur de Costa Oscura, donde empieza Vallefresno.",
    [6125] = "Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion.",
    [6126] = "Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar.",
    [6127] = "Usa el muestrario de Cima Calígine vacío para recoger una muestra de agua de uno de los estanques de la cima.$B$BLuego llévale el muestrario de Cima Calígine lleno a Tonga Tótem de Runa a El Cruce, en Los Baldíos.",
    [6128] = "Llévale 5 raíces de tierra y 5 cuernos de kodo a Tonga Tótem de Runa en El Cruce para que pueda confeccionar un bálsamo curativo.",
    [6129] = "Usa el bálsamo animal curativo sobre las 10 gacelas enfermas que se encuentran en la parte norte de Los Baldíos; así se curarán. Hemos recibido informes según los cuales se han avistado gacelas enfermas por la carretera que va de este a oeste en El Cruce.",
    [6130] = "Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros.",
    [6141] = "Habla con el hermano Anton en Desolace.",
    [6144] = "Ve a Entrañas y habla con Varimathras.",
    [6145] = "Vuelve a las Tierras de la Peste del Este y encuentra al mensajero carmesí. Mata al mensajero y recupera la Orden del Gran Cruzado.$B$BLleva el documento a Nathanos Clamañublo y espera sus instrucciones.",
    [6146] = "Viaja a Mano de Tyr, al sureste de la Hacienda de Marris. Una vez allí, da un mordisco a la manzana podrida. Entrega la Orden del Gran Cruzado al señor cruzado Valdemar con la protección de la forma de la Cruzada Escarlata.",
    [6147] = "Vuelve con Nathanos Clamañublo con la nueva información.|n",
    [6148] = "La Cruzada Escarlata se está moviendo. En algún lugar, a lo largo del camino que va de Mano de Tyr a Stratholme, encontrarás al Oráculo, Demetria, con su escolta. Da caza a Demetria y mátala. Vuelve junto a Nathanos Clamañublo si tienes éxito.",
    [6163] = "Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos.",
    [6402] = "Viaja hasta la Ciudad de Ventormenta y aventúrate tras las puertas de la ciudad. Habla con el escudero Rowe para que haga saber al mariscal Windsor sobre tu llegada.",
    [6403] = "Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!",
    [6501] = "Debes buscar por todo el mundo y encontrar un ser capaz de restaurar el poder del fragmento del Ojo del Dragón. La única información que tienes sobre dicho ser es que existe.",
    [6502] = "Tienes que recuperar la sangre de dragón Negro Campeón que tiene el general Drakkisath.",
    [6566] = "Escucha a Thrall.",
    [6567] = "Busca a Rexxar. El jefe de guerra te ha indicado dónde encontrarlo. Recorre los caminos de Desolace, entre la Sierra Espolón y Feralas.",
    [6568] = "Entrégale el testimonio de Rexxar a Myranda la Fada en las Tierras de la Peste del Oeste.",
    [6569] = "Viaja a la Cumbre de Roca Negra y recoge 20 ojos de dragauro negro. Cuando hayas terminado tu tarea regresa con Myranda la Fada.",
    [6570] = "Viaja a la Ciénaga de Fuego del Marjal Revolcafango y busca El Cubil de Brasaliza. Cuando estés dentro ponte el Amuleto de Subversión Dracónica y habla con Brasaliza.|n",
    [6582] = "Debes encontrar a Arúspice, el Campeón draco del Vuelo Azul y matarlo. Separa su cráneo de su cuerpo y llévaselo a Brasaliza.$B$BSabes que puedes encontrar a Arúspice en Cuna del Invierno.",
    [6583] = "Destruye al Campeón del Vuelo Verde, Somnus. Lleva su cráneo a Brasaliza.",
    [6584] = "Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su cráneo a Brasaliza.",
    [6585] = "Viaja a Grim Batol y encuentra a Axtroz, el Campeón del Vuelo Rojo. Destrúyelo y hazte con su cráneo. Llévaselo a Brasaliza.",
    [6601] = "Parece que la farsa se acabó. Sabes que el Amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en la Cumbre de Roca Negra. Quizá debas buscar a Rexxar y explicarle tu situación. Muéstrale el Amuleto Pirodraco apagado. Con suerte, él sabrá qué hacer.",
    [6602] = "Viaja a Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y entrégasela a Rexxar.",
    [6681] = "Lleva el Sello de Ravenholdt a Fahrad, que está en la Mansión Ravenholdt, en las colinas de Trabalomas.$B$BTendrás que poner a prueba tu ingenio por el camino. Ándate con ojo.",
    [6721] = "Habla con Dazalar en Dolanaar.",
    [6722] = "Habla con Dazalar en Dolanaar.",
    [6981] = "Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento resplandeciente.$B$BEntrega el fragmento como se te indique.",
    [7028] = "Recoge 25 tallas de cristal terádrico para Willow en Desolace.",
    [7029] = "Llena el vial cerúleo cubierto en el estanque naranja de Maraudon.$B$BAplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico.$B$BCura 8 plantas eliminando su sucesor tóxico e informa a Vark Marca de Guerra en la Aldea Cazasombras.",
    [7041] = "Llena el vial cerúleo cubierto en el estanque naranja de Maraudon.$B$BAplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico.$B$BCura 8 plantas eliminando su sucesor tóxico e informa a Talendria en Punta de Nijel.",
    [7044] = "Recupera las 2 partes del cetro de Celebras: la vara y el diamante de Celebras.$B$BEncuentra el modo de hablar con Celebras.",
    [7046] = "Ayuda a Celebras el Redimido mientras reconstruye el cetro de Celebras.$B$BHabla con él después del ritual.",
    [7064] = "Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace.",
    [7065] = "Mata a la princesa Theradras y ve a ver al vigilante Marandis a Punta de Nijel, en Desolace.",
    [7066] = "Busca a Remulos en Claro de la Luna y dale la semilla de vida.",
    [7067] = "Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace.",
    [7068] = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar.",
    [7070] = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango.",
    [7201] = "Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los gólems y a los creadores de gólems. Recuerdas que Vivian Lagrave también murmuró entre dientes algo sobre los elementales.",
    [7441] = "Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de Conjuros de Azj'Tordin, por cualquier medio.$B$BSi consigues hacerte con el libro de Conjuros, vuelve al Pabellón de Lariss de Feralas y busca a Azj'Tordin.",
    [7461] = "Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará.$B$BEntra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum.$B$BSi consigues completar esta misión, ve al patio a buscar a la ancestro Shen'dralar.",
    [7462] = "Vuelve a El Athenaeum y encuentra el tesoro de los Shen'dralar. ¡Reclama tu recompensa!",
    [7463] = "Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al Tradicionalista Lydros que está en El Athenaeum.",
    [7481] = "Busca a Telmius Buscasueños en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres.",
    [7482] = "Busca a Telmius Buscasueños en La Masacre. Vuelve al Bastión Plumaluna a informar a la erudita Runaespina de lo que hayas encontrado.",
    [7488] = "Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas.",
    [7489] = "Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas.",
    [7490] = "Llévale la cabeza de Onyxia a Thrall en Orgrimmar.",
    [7491] = "Busca al señor supremo Runthak en el Valle de la Fuerza.",
    [7492] = "Ve al Campamento Mojache de Feralas y habla con Talo Pezuñahendida.",
    [7493] = "¿$GUn matador:Una matadora; de dragones y $Gun peletero experimentado:una peletera experimentada;? No dejas de sorprenderme, $Ghéroe:heroína;. Me siento honrado.$B$BPor favor, acepta lo que estoy por enseñarte. Este conocimiento te será invaluable si vas a destruir lo que queda del Vuelo Negro.$B$BElabora la capa con las escamas de la madre de la progenie. Te protegerá a ti y a tus aliados del aliento incendiario del Señor de Roca Negra... Nefarian.",
    [7494] = "Habla con Latronicus Lanzaluna. Lo encontrarás en el Bastión Plumaluna de Feralas.",
    [7495] = "Llévale la cabeza de Onyxia al alto señor Bolvar Fordragón en Ventormenta.",
    [7496] = "Busca al mayor Mattingly en el Valle de los Héroes.",
    [7497] = "¿$GUn matador:Una matadora; de dragones y $Gun peletero experimentado:una peletera experimentada;? No dejas de sorprenderme, $Ghéroe:heroína;. Me siento honrado.$B$BPor favor, acepta lo que estoy por enseñarte. Este conocimiento te será invaluable si vas a destruir lo que queda del Vuelo Negro.$B$BElabora la capa con las escamas de la madre de la progenie. Te protegerá a ti y a tus aliados del aliento incendiario del Señor de Roca Negra... Nefarian.",
    [7498] = "Devuelve el libro a sus legítimos dueños.",
    [7499] = "Devuelve el libro a sus legítimos dueños.",
    [7500] = "Devuelve el libro a sus legítimos dueños.",
    [7501] = "Devuelve el libro a sus legítimos dueños.",
    [7502] = "Devuelve el libro a sus legítimos dueños.",
    [7503] = "Devuelve el libro a sus legítimos dueños.",
    [7504] = "Devuelve el libro a sus legítimos dueños.",
    [7505] = "Devuelve el libro a sus legítimos dueños.",
    [7506] = "Devuelve el libro a sus legítimos dueños.",
    [7507] = "Devuelve el compendio de matar dragones de Nostro a El Athenaeum.",
    [7508] = "Entrega la hoja élfica roma Tradicionalista Lydros.",
    [7509] = "Debes conseguir que Onyxia escupa fuego sobre la hoja antigua sin templar. Una vez hecho, recógela, su hoja estará candente. Pero ten cuidado: una hoja candente no permanecerá así para siempre, no tienes tiempo que perder.$B$BAntes de volver a mí, tienes que terminar lo empezado, debes matar a la bestia e introducir la hoja candente en su cadáver.$B$BHazlo y Quel'Serrar será tuya.",
    [7562] = "Habla con Mor'zul Sangredoble en las Estepas Ardientes.",
    [7563] = "Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes.",
    [7564] = "Llévale la caja de sangre a Gorzeeki Ojovago en las Estepas Ardientes.",
    [7604] = "Entrégale el contrato de La Hermandad del Torio a Lokhtos Tratoscuro si quieres recibir los planes de Sulfuron.",
    [7623] = "Cómprale pociones enigmáticas a Gorzeeki en las Estepas Ardientes.$B$BUsa las pociones para viajar por Jaedenar y habla con Lord Pesadilla.",
    [7624] = "Enfréntate a Ulathek y llévale el corazón del traidor a Lord Pesadilla en Jaedenar.",
    [7625] = "Cómprale polvo estelar xorothiano a Ur'dan. Llévaselo a Gorzeeki Ojovago en las Estepas Ardientes.",
    [7626] = "Llévale 10 elixires de poder de las sombras a Gorzeeki Ojovago en las Estepas Ardientes.",
    [7627] = "Llévale 6 fragmentos luminosos grandes y 25 minerales de hierro negro a Gorzeeki Ojosalvajes en Las Estepas Ardientes.",
    [7628] = "Llévale 35 dragontinas negras a Gorzeeki Ojovago en las Estepas Ardientes.",
    [7629] = "Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el papiro llévale el tarro a Gorzeeki Ojovago.",
    [7630] = "Llévale 3 barras de arcanita a Gorzeeki Ojovago en las Estepas Ardientes.",
    [7631] = "Lee las instrucciones de Mor'zul. Invoca a un corcel nefasto xorothiano, derrótalo y después vincula su espíritu al tuyo.",
    [7632] = "Encuentra al dueño de la hoja petrificada vieja. Buena suerte, $N; este es un mundo enorme...",
    [7634] = "Hastat el anciano te ha pedido que le lleves 1 tendón de dragón azul maduro. Si lo encuentras, llévaselo a Hastat a Frondavil.",
    [7635] = "Estoma el Anciano te ha pedido que le lleves 1 tendón de dragón Negro maduro. Si lo encontraras, llévaselo a Estoma a Frondavil.",
    [7636] = "Debes encontrar y destruir a estos 4 corruptores demoníacos:$B$BSimone la Seductora.$B$BKlinfran el Enloquecido.$B$BSolenor el Destripador.$B$BArtorius el Fatídico.$B$BDestruye a estas criaturas, vuelve a Frondavil y entrega sus cabezas a Vartrus el Ancestro.$B$BBusca pistas de su paradero en la corteza petrificada.$B$BDEBES completar esta misión tú $Gsolo:sola;.",
    [7637] = "Viaja a Forjaz y consigue el incensario de exorcismos del sumo sacerdote Rohan. Tendrás que hacer una donación de 150 monedas de oro para conseguirlo.",
    [7638] = "Habla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7639] = "Devuelve el incensario de exorcismos a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7640] = "Utiliza el incensario de exorcismos para expulsar los espíritus que atormentan el Valle del Terror. Cuando hayas matado 25 espíritus del Valle del Terror, vuelve a ver a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7641] = "Habla con Grimand Elmore en el Distrito de los Enanos, en Ventormenta.",
    [7642] = "Lleva 40 paños rúnicos, 6 barras de arcanita, 10 lágrimas de Arthas, 5 viales de agua sagrada de Stratholme y 150 monedas de oro a Grimand Elmore en el Distrito de los Enanos de Ventormenta.",
    [7643] = "Consigue comida para caballos para alimentar a un espíritu equino. Por lo visto, Merideth Carlson, en Costasur, tiene esa comida.$B$BVe a la mazmorra de La Masacre, en Feralas y mata a Tendris Alabeo. Al hacerlo, liberarás al antiguo espíritu equino. Dale la comida para caballos y lo aplacarás. Por último, dale la gualdrapa de arcanita para que la bendiga.",
    [7644] = "Devuelve la gualdrapa de arcanita bendita a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7645] = "Consigue 20 galletas enriquecidas con maná, ingrediente principal del alimento especial para caballos, y llévaselas a Merideth Carlson a las Laderas de Trabalomas, en Costasur. Solo El Alba Argenta fabrica esas galletas.$B$BTambién tienes que darle 50 piezas de oro para aplacar su orgullo herido.",
    [7646] = "Lleva un diamante de Azeroth y un diamante negro prístino a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7647] = "Utiliza el cristal de adivinación en el centro del sótano de El Gran Osario en Scholomance. Al hacerlo, aparecerán los espíritus que tienes que juzgar. Si derrotas a esos espíritus, aparecerá el Caballero de la Muerte Atracoscuro. Acaba con él y reclama el alma perdida del destrero caído.$B$BEntrega el alma redimida del destrero y la gualdrapa encantada bendecida al destrero caído de Atracoscuro.",
    [7648] = "Lleva la gualdrapa de arcanita a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta para que la inspeccione.",
    [7703] = "Encuentra el guante del Poderío de Gordok y llévaselo al capitán Kromcrush a La Masacre.$B$BSegún Kromcrush, una \"historia muy, muy vieja\" dice que Tortheldrin, un elfo \"asqueroso\" que se llamaba a sí mismo príncipe, robó el guantelete a uno de los reyes de Gordok.",
    [7761] = "¡Será estúpido ese orco! Al parecer, tienes que encontrar la enseña y ganar la marca de Drakkisath para poder acceder al orbe de orden.$B$BSegún la carta, el general Drakkisath guarda la enseña. Quizás deberías investigarlo.",
    [7785] = "Examina la vasija de renacer y devuélvesela al alto señor Demitrian.",
    [7786] = "Para liberar a Thunderaan el Hijo del Viento de su cárcel, debes entregarle al alto señor Demitrian en Silithus la mitad izquierda y la derecha de las ataduras del Hijo del Viento, 10 barras de elementium y la esencia del Señor del Fuego.",
    [7787] = "Lleva la hoja besada por el viento durmiente al alto señor Demitrian.",
    [7877] = "Vuelve a El Athenaeum y encuentra el tesoro de los Shen'dralar. ¡Reclama tu recompensa!",
    [8181] = "Habla con Yeh'kinya.",
    [8182] = "Habla con Molthor en Tuercespina.",
    [8323] = "Ermitaño Ortell quiere que le lleves 10 textos Crepusculares codificados.",
    [8410] = "Recoge una muestra de aire, fuego, tierra y agua para Bath'rah el Vigía del viento.",
    [8412] = "Lleva lo necesario para el tótem del espíritu a Bath'rah el Vigía del viento.",
    [8921] = "Vuelve a ver a Mux Cazamaná a Gadgetzan cuando tengas 1 conversor de arcanita delicado, 4 esencias eternas superiores, 10 unidades de aceite de escama pétrea, 25 cenizas volcánicas y 40 piezas de oro.",
    [8922] = "Lleva el frasco de sangre sellado a Mux Cazamaná a Gadgetzan, en Tanaris.",
    [8923] = "Lleva el frasco de veneno sellado a Mux Cazamaná a Gadgetzan.",
    [8924] = "Utiliza el destilador ectoplásmico cerca de los no-muertos incorpóreos y consigue 12 ectoplasmas agostados en Silithus, 12 ectoplasmas helados en Cuna del Invierno y 12 ectoplasmas estables en las Tierras de la Peste del Este. Llévaselos, junto con el destilador ectoplásmico, a Mux Cazamaná a Gadgetzan.",
    [8925] = "Encuentra al Señor del Magma Bokk en Las Estepas Ardientes, consigue el núcleo de arrabio y llévaselo a Mux Cazamaná a Gadgetzan.",
    [8928] = "Busca a un diablillo dentro de una cueva situada a la entrada de la Garganta Negro Rumor en la zona sur de Cuna del Invierno, compra una biela de energía vil elemental y vuelve a ver a Mux Cazamaná a Gadgetzan.",
    [8929] = "Usa el detector de fantasmas extradimensional en la entrada de Stratholme y habla con el fantasma de Anthion Harmon.",
    [8930] = "Usa el detector de fantasmas extradimensional en la entrada de Stratholme y habla con el fantasma de Anthion Harmon.",
    [8945] = "Ve a Stratholme y rescata a Ysida Harmon del Barón Osahendido.",
    [8946] = "Lleva el Guardapelo de Ysida a Anthion Harmon a las Tierras de la Peste del Este.",
    [8947] = "Lleva 3 barras de hierro negro, 20 retales de cuero encantado, 3 de tela lunar y 4 pellejos bastos curtidos a Anthion Harmon a las Tierras de la Peste del Este.",
    [8948] = "Lleva el estandarte de Provocación incompleto a Falrin Tallarbol que está en la biblioteca de La Masacre.",
    [8949] = "Reúne 25 abalorios de guerra de ogro de los ogros de La Masacre o de la Cumbre de Roca Negra y vuelve a El Athenaeum de La Masacre a hablar con Falrin Tallarbol.",
    [8950] = "Lleva a Falrin Tallarbol a La Masacre, lo siguiente: 1 esencia de espectro bufón, 4 runas oscuras y 8 fragmentos luminosos grandes.",
    [8960] = "Viaja hasta la Montaña Roca Negra y usa el detector de fantasmas extradimensionales para encontrar a Bodley cerca de la Cumbre de Roca Negra.",
    [8961] = "Recolecta la incendicita de Incendius, el ascua del Brasadivino y el rescoldo de las brasas junto con el blandón sagrado y llévaselos a Bodley en el interior de la Montaña Roca Negra.",
    [8962] = "Consigue restos de druida y llévaselos a Bodley en el interior de la Montaña Roca Negra.",
    [8963] = "Consigue una reliquia de la Aldea Brisa Estelar y llévasela a Bodley en el interior de la Montaña Roca Negra.",
    [8964] = "Consigue una espada luminosa de zelote y llévasela a Bodley en el interior de la Montaña Roca Negra.",
    [8965] = "Consigue cenizas de almas de los Desterrados y llévaselas a Bodley en el interior de la Montaña Roca Negra.",
    [8966] = "Usa el Blandón de Señalización para invocar al espíritu de Mor Pezuña Gris y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización.",
    [8967] = "Usa el Blandón de Señalización para invocar al espíritu de Isalien y mátala. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización.",
    [8968] = "Usa el Blandón de Señalización para invocar al espíritu de Jarien y Sothos y mátalos. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización.",
    [8969] = "Usa el Blandón de Señalización para invocar al espíritu de Kormok y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización.",
    [8970] = "Reúne 20 algas de sangre de los nagas de Strashaz y regresa junto a Bodley en el interior de la Montaña Roca Negra.",
    [8977] = "Lleva el detector de fantasmas extra dimensional a Deliana a Forjaz.",
    [8978] = "Lleva el detector de fantasmas extradimensional a Mokvar a Orgrimmar.",
    [8985] = "Consigue una reliquia de la Aldea Brisa Estelar y llévasela a Bodley en el interior de la Montaña Roca Negra.",
    [8986] = "Consigue restos de druida y llévaselos a Bodley en el interior de la Montaña Roca Negra.",
    [8987] = "Consigue una espada luminosa de zelote y llévasela a Bodley en el interior de la Montaña Roca Negra.",
    [8988] = "Consigue cenizas de almas de los Desterrados y llévaselas a Bodley en el interior de la Montaña Roca Negra.",
    [8989] = "Usa el Blandón de Señalización para invocar al espíritu de Mor Pezuña Gris y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con el amuleto de Lord Valthalak recompuesto y el Blandón de Señalización.",
    [8990] = "Usa el Blandón de Señalización para invocar al espíritu de Isalien y mátala. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con el amuleto de Lord Valthalak recompuesto y el Blandón de Señalización.",
    [8991] = "Usa el Blandón de Señalización para invocar al espíritu de Jarien y Sothos y mátalos. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con el amuleto de Lord Valthalak recompuesto y el Blandón de Señalización.",
    [8992] = "Usa el Blandón de Señalización para invocar al espíritu de Kormok y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con el amuleto de Lord Valthalak recompuesto y el Blandón de Señalización.",
